package com.personal.assistant.module.report.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.report.entity.GeneratedReport;import com.personal.assistant.module.report.service.ReportService;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;@RestController @RequestMapping("/api/reports")public class ReportController{private final ReportService service;public ReportController(ReportService service){this.service=service;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping public ApiResponse<List<GeneratedReport>>list(){return ApiResponse.success(service.list(uid()));}@PostMapping("/generate")public ApiResponse<GeneratedReport>generate(@RequestParam String type,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate reference){return ApiResponse.success(service.generate(uid(),type,reference==null?LocalDate.now():reference));}}
